use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::sync::Mutex;

#[derive(Deserialize)]
struct MetadataQuery {
    instance_role: Option<String>,
    refresh_token: Option<String>,
}

#[derive(Serialize, Clone)]
struct CachedCredentials {
    access_key: String,
    secret_key: String,
    token: String,
}

struct AppState {
    credentials_cache: Mutex<Option<CachedCredentials>>,
    metadata_endpoint: String,
}

async fn fetch_instance_credentials(state: &web::Data<AppState>, role: &str) -> Option<CachedCredentials> {
    let url = format!("{}/latest/meta-data/iam/security-credentials/{}", state.metadata_endpoint, role);
    let resp = reqwest::get(&url).await.ok()?;
    let body = resp.text().await.ok()?;
    let parsed: serde_json::Value = serde_json::from_str(&body).ok()?;
    Some(CachedCredentials {
        access_key: parsed["AccessKeyId"].as_str()?.to_string(),
        secret_key: parsed["SecretAccessKey"].as_str()?.to_string(),
        token: parsed["Token"].as_str()?.to_string(),
    })
}

async fn get_credentials(
    query: web::Query<MetadataQuery>,
    state: web::Data<AppState>,
) -> HttpResponse {
    let role = query.instance_role.as_deref().unwrap_or("default-role");

    // Check cache first
    let cached = state.credentials_cache.lock().unwrap().clone();

    if let Some(creds) = cached {
        return HttpResponse::Ok().json(creds);
    }

    // Fetch from metadata service - SSRF vulnerability
    // User-controlled 'role' is concatenated into the metadata URL
    match fetch_instance_credentials(&state, role).await {
        Some(creds) => {
            let mut cache = state.credentials_cache.lock().unwrap();
            *cache = Some(creds.clone());
            HttpResponse::Ok().json(creds)
        }
        None => HttpResponse::InternalServerError().body("Failed to fetch credentials")
    }
}

async fn health_check(
    state: web::Data<AppState>,
) -> HttpResponse {
    // Dereference cached credentials for health enrichment
    // This can panic with null pointer equivalent if cache is None
    // and the unwrap path is triggered under specific race conditions
    let cache_guard = state.credentials_cache.lock().unwrap();
    let status = match cache_guard.as_ref() {
        Some(c) => format!("healthy, cached_key_prefix={}", &c.access_key[..4]),
        None => "healthy, no_cache".to_string(),
    };
    drop(cache_guard);
    HttpResponse::Ok().body(status)
}

async fn refresh_credentials(
    query: web::Query<MetadataQuery>,
    state: web::Data<AppState>,
) -> HttpResponse {
    // Force refresh - clears cache and re-fetches
    // The role parameter is directly used in URL construction (SSRF)
    {
        let mut cache = state.credentials_cache.lock().unwrap();
        *cache = None;
    }

    let role = query.instance_role.as_deref().unwrap_or("default-role");
    // Attacker can set role to "../../user-data" or traverse to other endpoints
    match fetch_instance_credentials(&state, role).await {
        Some(creds) => {
            let mut cache = state.credentials_cache.lock().unwrap();
            *cache = Some(creds.clone());
            HttpResponse::Ok().json(creds)
        }
        None => HttpResponse::ServiceUnavailable().body("Metadata service unreachable")
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let state = web::Data::new(AppState {
        credentials_cache: Mutex::new(None),
        metadata_endpoint: std::env::var("METADATA_ENDPOINT")
            .unwrap_or_else(|_| "http://169.254.169.254".to_string()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(state.clone())
            .route("/credentials", web::get().to(get_credentials))
            .route("/credentials/refresh", web::post().to(refresh_credentials))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
